/**
 * Bundled demo artwork.
 *
 * NovaTech is a FICTIONAL brand created for this prototype — no real
 * organisation's marks are used. Both files live in `public/demo-assets/` and
 * are generated by `scripts/generate-demo-logos.mjs`, so they ship with the app
 * and survive a refresh without anything being downloaded or stored.
 */

export interface DemoAsset {
  id: string;
  label: string;
  caption: string;
  /** Public path, served statically. */
  src: string;
  mimeType: string;
}

export const NOVATECH_APPROVED: DemoAsset = {
  id: "novatech-approved",
  label: "NovaTech — approved logo",
  caption:
    "The official reference mark: navy wordmark, teal orbit and star, set tagline.",
  src: "/demo-assets/novatech-approved.png",
  mimeType: "image/png",
};

export const NOVATECH_MODIFIED: DemoAsset = {
  id: "novatech-modified",
  label: "NovaTech — modified logo",
  caption:
    "A version found in use, with deliberate deviations for the demo to catch.",
  src: "/demo-assets/novatech-modified.png",
  mimeType: "image/png",
};

/** Approved artwork held in the Brand DNA workspace. */
export const APPROVED_ASSETS: DemoAsset[] = [NOVATECH_APPROVED];
